import (
	"fmt"

	"github.com/malcolmston/rrule"
)

func main() {
	r, err := rrule.StrToRRule("DTSTART:19970902T090000Z\n" +
		"RRULE:FREQ=WEEKLY;INTERVAL=2;COUNT=4;WKST=SU;BYDAY=TU,TH")
	if err != nil {
		panic(err)
	}
	for _, t := range r.All() {
		fmt.Println(t.Format("Mon 2006-01-02"))
	}
	fmt.Println(r.String())
}

