package main

import (
	"fmt"
	"time"

	"github.com/malcolmston/rrule"
)

func main() {
	r, err := rrule.StrToRRule("DTSTART:19970902T090000Z\nRRULE:FREQ=DAILY")
	if err != nil {
		panic(err)
	}
	from := time.Date(1997, 12, 24, 0, 0, 0, 0, time.UTC)
	to := time.Date(1997, 12, 27, 0, 0, 0, 0, time.UTC)
	for _, t := range r.Between(from, to, true) {
		fmt.Println(t.Format("2006-01-02"))
	}
}

package main

import (
	"fmt"

	"github.com/malcolmston/rrule"
)

func main() {
	r, err := rrule.StrToRRule("DTSTART:19970902T090000Z\nRRULE:FREQ=MONTHLY;BYDAY=-1FR")
	if err != nil {
		panic(err)
	}
	next := r.Iterator()
	for {
		t, ok := next()
		if !ok || t.Year() > 1997 {
			break
		}
		fmt.Println(t.Format("Mon 2006-01-02"))
	}
}

package main

import (
	"fmt"
	"time"

	"github.com/malcolmston/rrule"
)

// implExampleStart is the anchor the examples share.
var implExampleStart = time.Date(1997, 9, 2, 9, 0, 0, 0, time.UTC)

func main() {
	weekly, err := rrule.New(rrule.Options{
		Freq:      rrule.Weekly,
		DTStart:   implExampleStart,
		ByWeekday: []rrule.Weekday{rrule.TU, rrule.TH},
		Count:     6,
	})
	if err != nil {
		panic(err)
	}
	s := rrule.NewSet()
	s.RRule(weekly)
	s.ExDate(time.Date(1997, 9, 4, 9, 0, 0, 0, time.UTC))
	s.RDate(time.Date(1997, 9, 5, 9, 0, 0, 0, time.UTC))
	for _, t := range s.All() {
		fmt.Println(t.Format("Mon 2006-01-02"))
	}
}
